import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for ShapeUtilities.equal(GeneralPath, GeneralPath).
 * Note: The provided source code contains a 'if (true) { return false; }' 
 * which makes the method always return false if p1 and p2 are non-null.
 */
public class ShapeUtilities_equal_TriageGen1Test {

    @Test
    public void testEqual_BothNull() {
        assertTrue(ShapeUtilities.equal(null, null));
    }

    @Test
    public void testEqual_P1Null_P2NotNull() {
        GeneralPath p2 = new GeneralPath();
        assertFalse(ShapeUtilities.equal(null, p2));
    }

    @Test
    public void testEqual_P1NotNull_P2Null() {
        GeneralPath p1 = new GeneralPath();
        assertFalse(ShapeUtilities.equal(p1, null));
    }

    @Test
    public void testEqual_DifferentWindingRule() {
        GeneralPath p1 = new GeneralPath(PathIterator.WIND_EVEN_ODD);
        GeneralPath p2 = new GeneralPath(PathIterator.WIND_NON_ZERO);
        assertFalse(ShapeUtilities.equal(p1, p2));
    }

    @Test
    public void testEqual_SameWindingRule_TriggersHardcodedFalse() {
        // Because of the 'if (true) { return false; }' in the provided source,
        // any non-null paths with same winding rule will hit this branch.
        GeneralPath p1 = new GeneralPath();
        GeneralPath p2 = new GeneralPath();

        // Even if they are identical, the logic provided contains a hardcoded return false.
        assertFalse(ShapeUtilities.equal(p1, p2));
    }

    /**
     * This test targets the branch where one iterator finishes before the other.
     * However, given the 'if (true)' block, this code is unreachable in the provided snippet.
     * We provide a test case that conceptually targets the path iterator mismatch.
     */
    @Test
    public void testEqual_IteratorMismatch() {
        GeneralPath p1 = new GeneralPath();
        p1.moveTo(0, 0);
        p1.lineTo(10, 10);

        GeneralPath p2 = new GeneralPath();
        p2.moveTo(0, 0);

        // Even though p1 has more segments than p2, the 'if (true)' will trigger first.
        assertFalse(ShapeUtilities.equal(p1, p2));
    }
}
